mapper.update:
update user_coupon
coupon_status = #{couponStatus}, order_id = #{orderId}, used_time = #{usedTime}, expire_time = #{expireTime}, update_time = #{updateTime}
where id = #{id}

mapper.select:
select uc.id, uc.user_id, uc.coupon_template_id, uc.coupon_code, uc.coupon_status, uc.order_id, uc.receive_time, uc.used_time, uc.expire_time, uc.create_time, uc.update_time, ct.coupon_name, ct.coupon_type, ct.threshold_amount, ct.discount_amount, ct.discount_rate, ct.end_time from user_coupon uc left join coupon_template ct on uc.coupon_template_id = ct.id where uc.user_id = #{userId}
and uc.coupon_status = #{couponStatus}
order by uc.id desc
